import{_ as a,o as t,c as r,ag as n}from"./chunks/framework.CbQjVMS6.js";const u=JSON.parse('{"title":"Projects","description":"","frontmatter":{},"headers":[],"relativePath":"projects.md","filePath":"projects.md","lastUpdated":1794023466000}'),s={name:"projects.md"};function o(i,e,p,l,d,c){return t(),r("div",null,[...e[0]||(e[0]=[n(`<h1 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h1><p>PieTeams maintains three open-source projects. They are separate tools, but they share a common design goal: make important information explicit, searchable and portable.</p><h2 id="piekbs-—-knowledge-search-for-ai-agents" tabindex="-1">PieKBS — knowledge search for AI agents <a class="header-anchor" href="#piekbs-—-knowledge-search-for-ai-agents" aria-label="Permalink to &quot;PieKBS — knowledge search for AI agents&quot;">​</a></h2><p><strong>Website:</strong> <a href="https://pieteams.github.io/piekbs/" target="_blank" rel="noreferrer">pieteams.github.io/piekbs</a><br><strong>Source:</strong> <a href="https://github.com/pieteams/piekbs" target="_blank" rel="noreferrer">github.com/pieteams/piekbs</a><br><strong>License:</strong> MIT<br><strong>Stack:</strong> Go, SQLite FTS5, Model Context Protocol</p><p>PieKBS is a local-first knowledge base built for agents rather than for chat interfaces. It watches a <code>raw/</code> directory, distills source documents into structured Markdown notes, and indexes the result with SQLite FTS5 and BM25 scoring. Agents then use three MCP tools:</p><ul><li><code>kb_search</code> — search the knowledge base and receive ranked pages</li><li><code>kb_page</code> — read a page in full</li><li><code>kb_add</code> — contribute new material</li></ul><p>Because the knowledge layer is plain Markdown, every change can be reviewed with <code>git diff</code>, linted and corrected. There is no embedding service to operate and no hidden vector store to explain.</p><p><strong>Good fit for:</strong> teams that want an auditable knowledge layer for coding agents, research agents or internal assistants.</p><h2 id="piemdm-—-master-data-management-for-enterprises" tabindex="-1">PieMDM — master data management for enterprises <a class="header-anchor" href="#piemdm-—-master-data-management-for-enterprises" aria-label="Permalink to &quot;PieMDM — master data management for enterprises&quot;">​</a></h2><p><strong>Website:</strong> <a href="https://pieteams.github.io/piemdm/" target="_blank" rel="noreferrer">pieteams.github.io/piemdm</a><br><strong>Source:</strong> <a href="https://github.com/pieteams/piemdm" target="_blank" rel="noreferrer">github.com/pieteams/piemdm</a><br><strong>License:</strong> MIT<br><strong>Stack:</strong> Go, Gin, GORM, MySQL, Redis, Vue 3, Vite</p><p>PieMDM is a full-stack platform for managing the data an organisation cannot afford to duplicate or contradict: customers, suppliers, materials, products, organisations and reference dictionaries.</p><p>The platform covers:</p><ul><li>data models, tables and fields with versioned definitions</li><li>dictionaries and reference data</li><li>entity creation, editing and approval</li><li>configurable approval flows</li><li>users, roles, menus and permissions</li><li>an OpenAPI surface plus generated SDK material</li></ul><p>A typical deployment runs the Go API and the Vue frontend in Docker Compose, with MySQL for persistence and Redis for caching and workflow state.</p><p><strong>Good fit for:</strong> enterprises and system integrators that need a self-hosted MDM foundation without licensing fees.</p><h2 id="pieplm-—-a-plm-blueprint-for-small-manufacturers" tabindex="-1">PiePLM — a PLM blueprint for small manufacturers <a class="header-anchor" href="#pieplm-—-a-plm-blueprint-for-small-manufacturers" aria-label="Permalink to &quot;PiePLM — a PLM blueprint for small manufacturers&quot;">​</a></h2><p><strong>Website:</strong> <a href="https://pieteams.github.io/pieplm/" target="_blank" rel="noreferrer">pieteams.github.io/pieplm</a><br><strong>Source:</strong> <a href="https://github.com/pieteams/pieplm" target="_blank" rel="noreferrer">github.com/pieteams/pieplm</a><br><strong>License:</strong> MIT<br><strong>Status:</strong> documentation and design phase</p><p>PiePLM explores how small and mid-sized manufacturers can manage product information across requirements, design, bill of materials, changes, quality and suppliers without the cost and complexity of a traditional PLM suite.</p><p>The public repository currently contains the project documentation and design notes. The site explains the problem, the intended architecture, the module boundaries and the planned API and MCP integration. It is deliberately published as a blueprint so that manufacturers and developers can evaluate the approach before implementation.</p><p><strong>Good fit for:</strong> manufacturing SMEs, PLM consultants and developers interested in an open alternative to proprietary suites.</p><h2 id="how-the-projects-relate" tabindex="-1">How the projects relate <a class="header-anchor" href="#how-the-projects-relate" aria-label="Permalink to &quot;How the projects relate&quot;">​</a></h2><p>The projects can be adopted independently. When used together, they form a coherent data chain:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PiePLM  product definitions, requirements, changes</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>PieMDM  governed master data: products, suppliers, materials</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>PieKBS  distilled knowledge and documents for people and agents</span></span></code></pre></div><p>Each step keeps its own source of truth and exposes a documented interface, so a team can start with one project and add another later without re-platforming.</p><h2 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h2><p>All projects use GitHub issues and pull requests. Read the <code>README.md</code> and <code>CONTRIBUTING.md</code> in the relevant repository before opening a large change. Documentation fixes are always welcome, including corrections to this website.</p>`,26)])])}const m=a(s,[["render",o]]);export{u as __pageData,m as default};
